import re
ws = r"C:\Users\糖蒜\Desktop\robrun_reference"
p = ws + r"\out\il2cpp\dump.cs"
lines = open(p, encoding='utf-8', errors='replace').readlines()
re_decl = re.compile(r'^(?:public |internal |private |protected )[^\n]*?\b(class|struct|interface|enum)\s+([A-Za-z0-9_<>`,\. ]+)')
idx=[]
for i,l in enumerate(lines):
    s=l.strip()
    if s.startswith('//'): continue
    m=re_decl.match(s)
    if m: idx.append((m.group(2).strip(), i+1))
d = {}
for n,ln in idx: d.setdefault(n, ln)
for n in ['SettlementDescription','TierParams','SectorParams','RealmEntry','RealmParams','RealmScheduleConfig','RealmTiersConfig','PlotSpotConfig','OwnedSettlementConfig','EvictConfig','PlotBuildingConfig','TierParams','TierDescription','SectorDescription','RealmVersion','RealmMapComputedConfig','RealmMapVersionComputedConfig','SettlementBuildingParams','SettlementTaxDescription','SettlementPriceRules','SettlementCashDatabaseData','SettlementCashPublicData','SettlementData','SettlementPlotClientPartData','SettlementPlotDatabasePartData','SettlementCommonPartData','OwnedSettlementData','RealmInfoData','RealmPopulationData','RealmClanConquestSectorsData','RealmClanConquestObjectsData','PlotSchemeDescription','PlotGradeDescription','MainBuildingDescription','OutbuildingDescription','CompoundWallDescription','PlotBuilderSlotTypeDescription','BuilderSlotModel','BuilderSlotsModel','PlotBuildingDefenseSettingsDescription','DefenseBlockDescription','MoneyWorkbenchDescription','CargoExchangeWorkbenchDescription','CargoOpenWorkbenchDescription','CargoProductionWorkbenchDescription','CargoChargeWorkbenchDescription','CryptoWorkbenchDescription','CollectionTableDescription','StorageDescription','ShelvingDescription','FirstAidCabinetDescription','ArchitectTableDescription','LocationPlotSpotsDescription','PlotSpotOrientedPoint','PlotConstructionSlotDescription','ExpiringResourceDescription','InventoryItemsPriceDescription','RealmSectorsConfig','SectorNeighboursRealmVersion0','RealmVersions','ConfiscationDescription','ConfiscationModel','ClanConfig','ClanRankDescription','TaxCollectionSettlementModel','CashLootNodeModel','VendorTreeNodeViewDescription','VendorTreeViewDescription','MapBuildingDescription','MapViewDescription','RealmGridViewDescription','RealmSectorCenterView','RealmLocationView','LocationViewDescription','LocationDescription','TutorialStepViewDescription','BuffViewDescription','CodexViewDescription','BattlePassViewDescription','PrisonViewDescription','WantedPointsConfig','ImprisonmentYearsByDataModel','ReputationViewDescription','VehicleDescription','CarUpgradeDescription','HelicopterDescription','NpcDescription','TraderDescription','BuyerDescription','CargoExchangerDescription','ElevatorDescription','DoorDescription','WindowBlindsDescription','TerrainCarveZoneDescription','KinematicObjectsControllerDescription','WaterZoneDescription','PlotContainerDescription','PlotMoneyWorkbenchDescription','PlotLaunderingCableDescription','PlotDefenseBlockDescription','PlotGarageDescription','PlotHelicopterSlotDescription','MainBuildingDoorSlotDescription','StorageSlotDescription','ShelvingSlotDescription','MainBuildingPlotWaterZoneSlotDescription','FirstAidCabinetSlotDescription','PlotWindowBlindsDescription','MainBuildingWindowBlindsAffectionDescription']:
    print(f"{n}\t{d.get(n,'MISSING')}")
